step_4.solutionCode:
import threading

SHARED = ("code", "global", "heap", "file")
PER_THREAD = ("stack", "pc", "registers")


def scope_of(part):
    if part in SHARED:
        return "shared"
    if part in PER_THREAD:
        return "per-thread"
    raise ValueError("unknown part: " + str(part))


def who_am_i():
    return threading.current_thread().name


if __name__ == "__main__":
    print(scope_of("heap"))
    print(who_am_i())

